-- ===========================================================================
-- Hand-written part (prisma/README.md). Phase 2 M5: hygiene. Runs as crm_migrator. Adds;
-- changes no existing policy, role, grant or definer function. Existing objects touched: lead (new column + CHECK, 3 new UPDATE
-- column grants, one new trigger) and the lead_activity_type CHECK (widened, as in 0004).
-- New privileges for existing roles: crm_app (new tables, 3 lead columns), crm_definer (column
-- SELECT/UPDATE on export_job for the two cleanup functions), crm_cleanup (EXECUTE on the two
-- cleanup functions). crm_auth and crm_platform get nothing.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- 1. Lead: archive / merge (D1) / custom values (D5)
-- ---------------------------------------------------------------------------
ALTER TABLE lead
  ADD CONSTRAINT lead_custom_fields CHECK (jsonb_typeof(custom_fields) = 'object'
    AND pg_column_size(custom_fields) <= 16384);

-- A merged lead is a frozen tombstone (D1: its history stays where it is and is read through the
-- pointer); so is a deleted one [F1]. archived_at is set to the transaction time or cleared,
-- never back- or forward-dated. The merge target must be a live, unmerged, unarchived lead of the
-- same org [F2]; it is locked FOR UPDATE, so two concurrent merges (A into B, B into A) cannot
-- both commit and form a cycle [F3] (READ COMMITTED re-checks the target's latest version; a
-- crossing pair deadlocks and one is aborted). The function is SECURITY INVOKER: RLS hides other
-- orgs' rows, and the composite FK (org_id, merged_into_lead_id) already forces the same org.
CREATE FUNCTION app.lead_hygiene_guard() RETURNS trigger
  LANGUAGE plpgsql SET search_path = pg_catalog, pg_temp
  AS $$
BEGIN
  IF OLD.merged_into_lead_id IS NOT NULL OR OLD.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'lead % was merged or deleted and cannot change', OLD.id
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.archived_at IS DISTINCT FROM OLD.archived_at
     AND NEW.archived_at IS NOT NULL AND NEW.archived_at <> now() THEN
    RAISE EXCEPTION 'lead % archive time must be now', OLD.id USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.merged_into_lead_id IS NOT NULL THEN
    PERFORM 1 FROM public.lead t
      WHERE t.id = NEW.merged_into_lead_id AND t.org_id = NEW.org_id
        AND t.merged_into_lead_id IS NULL AND t.deleted_at IS NULL AND t.archived_at IS NULL
      FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'merge target for lead % is not a live lead', OLD.id
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION app.lead_hygiene_guard() FROM PUBLIC;
CREATE TRIGGER lead_hygiene_guard BEFORE UPDATE ON lead
  FOR EACH ROW EXECUTE FUNCTION app.lead_hygiene_guard();

ALTER TABLE lead_activity DROP CONSTRAINT lead_activity_type;
ALTER TABLE lead_activity
  ADD CONSTRAINT lead_activity_type CHECK (type IN ('CREATED', 'ENQUIRY', 'ASSIGNED', 'STAGE',
    'NOTE', 'FIELD_CHANGED', 'ARCHIVED', 'RESTORED', 'MERGED'));

-- D4: deleted_at stays ungranted; hard delete / erasure is a separate later proposal.
GRANT UPDATE (archived_at, merged_into_lead_id, custom_fields) ON lead TO crm_app;

-- ---------------------------------------------------------------------------
-- 2. Custom field definitions (D5: <= 30 active per org)
-- ---------------------------------------------------------------------------
ALTER TABLE custom_field_definition
  ADD CONSTRAINT custom_field_definition_key CHECK (key ~ '^[a-z][a-z0-9_]{1,39}$'),
  ADD CONSTRAINT custom_field_definition_label CHECK (length(btrim(label)) BETWEEN 1 AND 100),
  ADD CONSTRAINT custom_field_definition_type CHECK (type IN ('text', 'number', 'date',
    'single_select', 'multi_select', 'boolean')),
  -- [F4] options are an array of 1-100 character strings, only for select types. (jsonpath has
  -- no string length; .size() on a string is 1 in lax mode, hence the regex.)
  ADD CONSTRAINT custom_field_definition_options CHECK (jsonb_typeof(options) = 'array'
    AND jsonb_array_length(options) <= 50
    AND (type IN ('single_select', 'multi_select')) = (jsonb_array_length(options) > 0)
    AND NOT jsonb_path_exists(options,
      '$[*] ? (@.type() != "string" || !(@ like_regex "^.{1,100}$" flag "s"))')),
  ADD CONSTRAINT custom_field_definition_position CHECK (position BETWEEN 0 AND 1000),
  ADD CONSTRAINT custom_field_definition_version CHECK (version >= 1);

-- The org's active count is checked under a per-org transaction advisory lock, so two concurrent
-- inserts or un-archives cannot both pass. Under READ COMMITTED (the application's level) each
-- statement takes a fresh snapshot, so the second waiter sees the first's committed row.
-- REPEATABLE READ would reuse an old snapshot and could miss it, so it is refused [F5];
-- SERIALIZABLE is safe (the conflict aborts one transaction).
CREATE FUNCTION app.custom_field_limit() RETURNS trigger
  LANGUAGE plpgsql SET search_path = pg_catalog, pg_temp
  AS $$
BEGIN
  IF NEW.archived_at IS NULL THEN
    IF current_setting('transaction_isolation') = 'repeatable read' THEN
      RAISE EXCEPTION 'custom field changes need READ COMMITTED or SERIALIZABLE'
        USING ERRCODE = 'invalid_transaction_state';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('custom-field-limit:' || NEW.org_id::text, 0));
    IF (SELECT count(*) FROM public.custom_field_definition d
        WHERE d.org_id = NEW.org_id AND d.archived_at IS NULL AND d.id <> NEW.id) >= 30 THEN
      RAISE EXCEPTION 'at most 30 active custom fields' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION app.custom_field_limit() FROM PUBLIC;
CREATE TRIGGER custom_field_limit BEFORE INSERT OR UPDATE OF archived_at ON custom_field_definition
  FOR EACH ROW EXECUTE FUNCTION app.custom_field_limit();

-- ---------------------------------------------------------------------------
-- 3. Duplicate review queue. Possible duplicates are never merged automatically, and (D2) an
--    enquiry matching an archived lead never restores it: both become review cases that only an
--    explicit, attributed decision closes.
-- ---------------------------------------------------------------------------
ALTER TABLE lead_duplicate_match
  ADD CONSTRAINT lead_duplicate_match_type CHECK (match_type IN ('PHONE_ALT', 'EMAIL',
    'NAME_SIMILAR', 'ARCHIVED_ENQUIRY')),
  -- Pair cases name two different leads and no enquiry; archived cases one lead and its enquiry.
  ADD CONSTRAINT lead_duplicate_match_shape CHECK (CASE WHEN match_type = 'ARCHIVED_ENQUIRY'
    THEN candidate_lead_id IS NULL AND enquiry_id IS NOT NULL
    ELSE candidate_lead_id IS NOT NULL AND enquiry_id IS NULL AND candidate_lead_id <> lead_id END),
  ADD CONSTRAINT lead_duplicate_match_status CHECK (status = 'OPEN' OR CASE
    WHEN match_type = 'ARCHIVED_ENQUIRY' THEN status IN ('RESTORED', 'KEPT_ARCHIVED')
    ELSE status IN ('MERGED', 'DISMISSED') END),
  ADD CONSTRAINT lead_duplicate_match_score CHECK (score BETWEEN 0 AND 1),
  ADD CONSTRAINT lead_duplicate_match_resolved CHECK ((status = 'OPEN') = (resolved_at IS NULL)
    AND (status = 'OPEN') = (resolved_by IS NULL));
-- [F6] A pair is one case whichever lead was seen first (the draft allowed (A,B) and (B,A)).
-- A dismissed pair stays dismissed: it is not re-raised.
CREATE UNIQUE INDEX lead_duplicate_match_pair_uq ON lead_duplicate_match
  (org_id, least(lead_id, candidate_lead_id), greatest(lead_id, candidate_lead_id))
  WHERE candidate_lead_id IS NOT NULL;
-- One case per enquiry, and at most one open archived case per lead (later enquiries for the same
-- archived lead are attached and wait for that decision).
CREATE UNIQUE INDEX lead_duplicate_match_enquiry_uq ON lead_duplicate_match (org_id, enquiry_id)
  WHERE enquiry_id IS NOT NULL;
CREATE UNIQUE INDEX lead_duplicate_match_archived_open_uq ON lead_duplicate_match (org_id, lead_id)
  WHERE match_type = 'ARCHIVED_ENQUIRY' AND status = 'OPEN';

-- [F7] The outcome must be true when it is recorded (same transaction, after the lead change):
-- MERGED needs one lead merged into the other; RESTORED needs the lead un-archived;
-- KEPT_ARCHIVED needs it still archived. New cases name live leads; an archived case names an
-- archived lead and an enquiry of that lead. SECURITY INVOKER: lookups see only the session org.
CREATE FUNCTION app.duplicate_match_guard() RETURNS trigger
  LANGUAGE plpgsql SET search_path = pg_catalog, pg_temp
  AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NOT EXISTS (SELECT 1 FROM public.lead l WHERE l.id = NEW.lead_id AND l.org_id = NEW.org_id
                     AND l.merged_into_lead_id IS NULL AND l.deleted_at IS NULL
                     AND (l.archived_at IS NOT NULL) = (NEW.match_type = 'ARCHIVED_ENQUIRY')) THEN
      RAISE EXCEPTION 'duplicate case names a lead in the wrong state' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.candidate_lead_id IS NOT NULL AND NOT EXISTS (
         SELECT 1 FROM public.lead l WHERE l.id = NEW.candidate_lead_id AND l.org_id = NEW.org_id
           AND l.merged_into_lead_id IS NULL AND l.deleted_at IS NULL) THEN
      RAISE EXCEPTION 'duplicate candidate is not a live lead' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.enquiry_id IS NOT NULL AND NOT EXISTS (
         SELECT 1 FROM public.lead_enquiry e WHERE e.id = NEW.enquiry_id
           AND e.org_id = NEW.org_id AND e.lead_id = NEW.lead_id) THEN
      RAISE EXCEPTION 'enquiry does not belong to the archived lead' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.status = 'MERGED' AND NOT EXISTS (
       SELECT 1 FROM public.lead l WHERE l.org_id = NEW.org_id
         AND ((l.id = NEW.lead_id AND l.merged_into_lead_id = NEW.candidate_lead_id)
           OR (l.id = NEW.candidate_lead_id AND l.merged_into_lead_id = NEW.lead_id))) THEN
    RAISE EXCEPTION 'duplicate case % was not merged', OLD.id USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status IN ('RESTORED', 'KEPT_ARCHIVED') AND NOT EXISTS (
       SELECT 1 FROM public.lead l WHERE l.id = NEW.lead_id AND l.org_id = NEW.org_id
         AND l.merged_into_lead_id IS NULL
         AND (l.archived_at IS NULL) = (NEW.status = 'RESTORED')) THEN
    RAISE EXCEPTION 'duplicate case % outcome does not match the lead', OLD.id
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION app.duplicate_match_guard() FROM PUBLIC;
CREATE TRIGGER duplicate_match_guard BEFORE INSERT OR UPDATE ON lead_duplicate_match
  FOR EACH ROW EXECUTE FUNCTION app.duplicate_match_guard();

-- ---------------------------------------------------------------------------
-- 4. Export jobs (D3, T5): Owner-only, requester-only, single download inside 15 minutes,
--    file purged no later than 1 hour after the job was created.
-- ---------------------------------------------------------------------------
ALTER TABLE export_job
  ADD CONSTRAINT export_job_status CHECK (status IN ('QUEUED', 'RUNNING', 'READY', 'DOWNLOADED',
    'EXPIRED', 'FAILED')),
  ADD CONSTRAINT export_job_format CHECK (format IN ('csv')),
  -- [F8] filters are a small object (the audit entry copies them; no free-text blobs).
  ADD CONSTRAINT export_job_filters CHECK (jsonb_typeof(filters) = 'object'
    AND pg_column_size(filters) <= 4096),
  ADD CONSTRAINT export_job_rows CHECK (row_count IS NULL OR row_count BETWEEN 0 AND 50000),
  ADD CONSTRAINT export_job_storage_key CHECK (storage_key ~ ('^orgs/' || org_id::text ||
    '/exports/' || id::text || '/[0-9a-f]{32}\.csv$')),
  ADD CONSTRAINT export_job_sha256 CHECK (sha256 IS NULL OR length(sha256) = 32),
  -- [F9] The draft's window CHECK passed when finished_at was NULL (NULL is not false), leaving
  -- expires_at unbounded. A ready or downloaded job now has every field set, its window is at
  -- most 15 minutes and ends before the file is purged.
  ADD CONSTRAINT export_job_ready CHECK (status NOT IN ('READY', 'DOWNLOADED')
    OR (finished_at IS NOT NULL AND expires_at IS NOT NULL AND row_count IS NOT NULL
        AND sha256 IS NOT NULL AND expires_at <= finished_at + interval '15 minutes'
        AND expires_at <= purge_file_after)),
  ADD CONSTRAINT export_job_downloaded CHECK ((status = 'DOWNLOADED') = (downloaded_at IS NOT NULL)),
  -- [F10] Retention is absolute: the draft's policy re-measured "now() + 1 h" on every update, so
  -- each update could extend the file's life. created_at is not updatable.
  ADD CONSTRAINT export_job_retention CHECK (purge_file_after <= created_at + interval '1 hour'),
  ADD CONSTRAINT export_job_version CHECK (version >= 1),
  ADD CONSTRAINT export_job_error_code CHECK (error_code IS NULL OR error_code ~ '^[A-Z0-9_]{1,50}$');
CREATE INDEX export_job_purge_idx ON export_job (purge_file_after) WHERE file_deleted_at IS NULL;

-- [F11] State machine with the facts each transition records at the transaction time.
-- Finished jobs are frozen except the cleanup marker; the marker is set once, at now(), and only
-- together with a finished status (cleanup closes an unfinished job); results cannot be rewritten
-- after READY; retention can only shrink. The download is single use: READY -> DOWNLOADED only
-- inside the window and before the file is purged; concurrent claims serialise on the row lock and
-- the loser's conditional UPDATE matches no row (the application streams only after a 1-row claim).
CREATE FUNCTION app.export_job_guard() RETURNS trigger
  LANGUAGE plpgsql SET search_path = pg_catalog, pg_temp
  AS $$
BEGIN
  IF NEW.file_deleted_at IS DISTINCT FROM OLD.file_deleted_at
     AND (OLD.file_deleted_at IS NOT NULL OR NEW.file_deleted_at <> now()
          OR NEW.status IN ('QUEUED', 'RUNNING', 'READY')) THEN
    RAISE EXCEPTION 'export % file marker is set once, now, on a finished job', OLD.id
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.purge_file_after > OLD.purge_file_after THEN
    RAISE EXCEPTION 'export % retention cannot grow', OLD.id USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.status IN ('DOWNLOADED', 'EXPIRED', 'FAILED') THEN
    IF (to_jsonb(NEW) - ARRAY['file_deleted_at', 'updated_at', 'version'])
       IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['file_deleted_at', 'updated_at', 'version']) THEN
      RAISE EXCEPTION 'export % is finished', OLD.id USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status
     AND NEW.status <> 'FAILED'
     AND (OLD.status, NEW.status) NOT IN (('QUEUED', 'RUNNING'), ('RUNNING', 'READY'),
       ('READY', 'DOWNLOADED'), ('READY', 'EXPIRED'), ('QUEUED', 'EXPIRED')) THEN
    RAISE EXCEPTION 'export % cannot go from % to %', OLD.id, OLD.status, NEW.status
      USING ERRCODE = 'check_violation';
  END IF;
  -- [A1] The list search text (filters.q) may be a name or phone number. Filters can change only
  -- by dropping it, and a job cannot finish while it is still there (the audit entry keeps only
  -- "a search was used"). Finished jobs are frozen above, so it never comes back.
  IF NEW.filters IS DISTINCT FROM OLD.filters AND NEW.filters IS DISTINCT FROM (OLD.filters - 'q') THEN
    RAISE EXCEPTION 'export % filters can only lose the search text', OLD.id
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status IN ('DOWNLOADED', 'EXPIRED', 'FAILED') AND NEW.filters ? 'q' THEN
    RAISE EXCEPTION 'export % must drop the search text when it finishes', OLD.id
      USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.status = 'QUEUED' AND NEW.status = 'RUNNING' AND NEW.started_at IS DISTINCT FROM now() THEN
    RAISE EXCEPTION 'export % start time must be now', OLD.id USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.status = 'RUNNING' AND NEW.status = 'READY'
     AND (NEW.finished_at IS DISTINCT FROM now() OR NEW.expires_at > now() + interval '15 minutes') THEN
    RAISE EXCEPTION 'export % ready time must be now, window <= 15 minutes', OLD.id
      USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.status = 'READY'
     AND (NEW.row_count, NEW.sha256, NEW.started_at, NEW.finished_at, NEW.expires_at)
         IS DISTINCT FROM (OLD.row_count, OLD.sha256, OLD.started_at, OLD.finished_at, OLD.expires_at) THEN
    RAISE EXCEPTION 'export % result is fixed once ready', OLD.id USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status = 'DOWNLOADED'
     AND (now() >= OLD.expires_at OR now() >= OLD.purge_file_after
          OR OLD.file_deleted_at IS NOT NULL OR NEW.downloaded_at IS DISTINCT FROM now()) THEN
    RAISE EXCEPTION 'export % download window has closed', OLD.id USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION app.export_job_guard() FROM PUBLIC;
CREATE TRIGGER export_job_guard BEFORE UPDATE ON export_job
  FOR EACH ROW EXECUTE FUNCTION app.export_job_guard();

-- [F12] Rate limit (NFR-046): at most 5 export requests per requester per rolling 24 hours,
-- counted under a per-requester advisory lock (same concurrency reasoning as custom_field_limit).
CREATE FUNCTION app.export_job_quota() RETURNS trigger
  LANGUAGE plpgsql SET search_path = pg_catalog, pg_temp
  AS $$
BEGIN
  IF current_setting('transaction_isolation') = 'repeatable read' THEN
    RAISE EXCEPTION 'export requests need READ COMMITTED or SERIALIZABLE'
      USING ERRCODE = 'invalid_transaction_state';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'export-quota:' || NEW.org_id::text || ':' || NEW.requested_by::text, 0));
  IF (SELECT count(*) FROM public.export_job j
      WHERE j.org_id = NEW.org_id AND j.requested_by = NEW.requested_by
        AND j.created_at > now() - interval '24 hours') >= 5 THEN
    RAISE EXCEPTION 'export limit reached' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION app.export_job_quota() FROM PUBLIC;
CREATE TRIGGER export_job_quota BEFORE INSERT ON export_job
  FOR EACH ROW EXECUTE FUNCTION app.export_job_quota();

-- ---------------------------------------------------------------------------
-- 5. RLS: ENABLE + FORCE, maintenance, tenant isolation (same text as 0002–0005)
-- ---------------------------------------------------------------------------
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['custom_field_definition', 'lead_duplicate_match', 'export_job'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY maintenance ON %I FOR ALL TO crm_migrator USING (true) WITH CHECK (true)', t);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I FOR ALL TO crm_app '
      'USING (org_id = (SELECT app.current_org_id())) '
      'WITH CHECK (org_id = (SELECT app.current_org_id()))', t);
  END LOOP;
END $$;

-- RESTRICTIVE policies: they narrow tenant_isolation, never widen it.
CREATE POLICY actor_is_session_user ON custom_field_definition AS RESTRICTIVE FOR INSERT TO crm_app
  WITH CHECK (created_by = (SELECT app.current_user_id()) AND created_at = now());

-- [F13] The draft had no insert policy: any crm_app session could insert a case already
-- "resolved" by someone else. Cases start OPEN, now, attributed to the session (NULL = system).
CREATE POLICY first_state_open ON lead_duplicate_match AS RESTRICTIVE FOR INSERT TO crm_app
  WITH CHECK (status = 'OPEN' AND resolved_by IS NULL AND resolved_at IS NULL
              AND created_at = now()
              AND detected_by IS NOT DISTINCT FROM (SELECT app.current_user_id()));
-- Resolved once (only OPEN rows are updatable), by the session user, at the transaction time.
-- A concurrent second resolver's UPDATE re-checks the row after the first commits and matches
-- nothing; the application treats 0 rows as "already resolved".
CREATE POLICY resolver_is_session_user ON lead_duplicate_match AS RESTRICTIVE FOR UPDATE TO crm_app
  USING (status = 'OPEN')
  WITH CHECK (status <> 'OPEN' AND resolved_by = (SELECT app.current_user_id())
              AND resolved_at = now());

-- Exports are personal: only the requester sees, builds (the worker acts as the requester through
-- memberContext) or downloads them; the rest of the org sees the audit entries only.
CREATE POLICY requester_only ON export_job AS RESTRICTIVE FOR ALL TO crm_app
  USING (requested_by = (SELECT app.current_user_id()))
  WITH CHECK (requested_by = (SELECT app.current_user_id()));
-- [F14] D3 Owner-only, also in the database: requesting, building and downloading need the session
-- user to be an ACTIVE owner of the session org now (a demoted or suspended owner's job stalls and
-- is purged). Support/platform sessions are not members and never match.
CREATE POLICY owner_requests ON export_job AS RESTRICTIVE FOR INSERT TO crm_app
  WITH CHECK (EXISTS (SELECT 1 FROM organization_membership m
                      WHERE m.org_id = (SELECT app.current_org_id())
                        AND m.user_id = (SELECT app.current_user_id())
                        AND m.role = 'owner' AND m.status = 'ACTIVE'));
CREATE POLICY owner_updates ON export_job AS RESTRICTIVE FOR UPDATE TO crm_app
  USING (EXISTS (SELECT 1 FROM organization_membership m
                 WHERE m.org_id = (SELECT app.current_org_id())
                   AND m.user_id = (SELECT app.current_user_id())
                   AND m.role = 'owner' AND m.status = 'ACTIVE'))
  WITH CHECK (true);
CREATE POLICY first_state_now ON export_job AS RESTRICTIVE FOR INSERT TO crm_app
  WITH CHECK (status = 'QUEUED' AND created_at = now() AND started_at IS NULL
              AND finished_at IS NULL AND expires_at IS NULL AND downloaded_at IS NULL
              AND row_count IS NULL AND sha256 IS NULL AND error_code IS NULL
              AND file_deleted_at IS NULL);

-- ---------------------------------------------------------------------------
-- 6. crm_app grants (minimum). No DELETE anywhere. crm_auth / crm_platform get nothing.
--    Never updatable: identity, tenant, actor and creation columns; custom field key and type
--    (changing a type would reinterpret stored values); duplicate case leads/enquiry/type;
--    export requester, format, storage key, created_at and the cleanup marker. Export filters
--    are updatable only to drop the search text (export_job_guard [A1]).
-- ---------------------------------------------------------------------------
GRANT SELECT, INSERT ON custom_field_definition, lead_duplicate_match, export_job TO crm_app;
GRANT UPDATE (label, required, options, position, archived_at, updated_at, version)
  ON custom_field_definition TO crm_app;
GRANT UPDATE (status, resolved_by, resolved_at) ON lead_duplicate_match TO crm_app;
GRANT UPDATE (status, filters, row_count, sha256, error_code, version, updated_at, started_at,
  finished_at, expires_at, downloaded_at, purge_file_after) ON export_job TO crm_app;

-- ---------------------------------------------------------------------------
-- 7. Export file cleanup, callable ONLY by crm_cleanup (same pattern as app.import_files_due).
--    requester_only hides export rows from system tenant sessions, so the marker is written by a
--    second definer function, not by crm_app: it marks only a row that is due, in the given org,
--    and closes it (QUEUED/READY -> EXPIRED, RUNNING -> FAILED), dropping the search text [A1]. The worker calls it after the
--    storage delete succeeded for a key that keyBelongsTo(org, 'exports', job).
-- ---------------------------------------------------------------------------
CREATE POLICY definer_lookup ON export_job FOR SELECT TO crm_definer USING (true);
CREATE POLICY definer_mark ON export_job FOR UPDATE TO crm_definer
  USING (file_deleted_at IS NULL AND purge_file_after <= now())
  WITH CHECK (file_deleted_at IS NOT NULL);
GRANT SELECT (id, org_id, status, filters, storage_key, error_code, purge_file_after,
  file_deleted_at) ON export_job TO crm_definer;
GRANT UPDATE (status, filters, error_code, updated_at, file_deleted_at) ON export_job TO crm_definer;

CREATE FUNCTION app.export_files_due(p_limit integer)
  RETURNS TABLE (org_id uuid, export_job_id uuid, storage_key text)
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT j.org_id, j.id, j.storage_key
    FROM public.export_job j
    WHERE j.file_deleted_at IS NULL AND j.purge_file_after <= now()
    ORDER BY j.purge_file_after
    LIMIT least(greatest(p_limit, 0), 500)
  $$;

CREATE FUNCTION app.export_file_deleted(p_org_id uuid, p_export_job_id uuid) RETURNS boolean
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
BEGIN
  UPDATE public.export_job j
     SET file_deleted_at = now(), updated_at = now(), filters = j.filters - 'q',
         status = CASE WHEN j.status IN ('QUEUED', 'READY') THEN 'EXPIRED'
                       WHEN j.status = 'RUNNING' THEN 'FAILED' ELSE j.status END,
         error_code = CASE WHEN j.status = 'RUNNING' THEN 'EXPIRED_BEFORE_READY'
                           ELSE j.error_code END
   WHERE j.id = p_export_job_id AND j.org_id = p_org_id
     AND j.file_deleted_at IS NULL AND j.purge_file_after <= now();
  RETURN FOUND;
END $$;

ALTER FUNCTION app.export_files_due(integer) OWNER TO crm_definer;
ALTER FUNCTION app.export_file_deleted(uuid, uuid) OWNER TO crm_definer;
REVOKE ALL ON FUNCTION app.export_files_due(integer), app.export_file_deleted(uuid, uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION app.export_files_due(integer), app.export_file_deleted(uuid, uuid)
  FROM crm_app, crm_auth, crm_platform;
-- USAGE on schema app was granted to crm_cleanup in 0005; nothing else is added for it.
GRANT EXECUTE ON FUNCTION app.export_files_due(integer), app.export_file_deleted(uuid, uuid)
  TO crm_cleanup;
